contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a single transfer from this test contract to some recipient or vice-versa
    // params:
    // fromIsAllowed: if true, make this contract be the sender with allowed role behavior (buy path)
    // toIsAllowed: if true, make recipient be allowed role (sell path)
    // recipient: target address to transfer to
    // amount: token amount tAmount to transfer
    function run(bool fromIsAllowed, bool toIsAllowed, address recipient, uint256 amount) public payable {
        require(recipient != address(0));
        // Ensure this contract has some tokens to send when acting as sender: read its balance
        uint256 beforeTotal = c.totalSupply();

        // read balances and txReward before
        uint256 balThisBefore = c.balanceOf(address(this));
        uint256 balRecBefore = c.balanceOf(recipient);
        uint256 balContractBefore = c.balanceOf(address(c));
        uint256 txRewardThisBefore = c.txReward(address(this));
        uint256 txRewardRecBefore = c.txReward(recipient);

        // Owner-only functions exist; but we cannot call them as we are not owner. We only need to set allowed roles indirectly.
        // The contract exposes no public setter for _allowedRoles; however the constructor of C likely set roles such that msg.sender (deployer) had balances and owner. In this test msg.sender is this deployed test contract. We cannot modify private roles.
        // So we will attempt two flows: if fromIsAllowed or toIsAllowed are false, transfer should follow fallback path; if true, transfer will try allowed-role branch and may revert due to unauthorized role — capture revert.

        bool reverted = false;
        // perform a transfer either sending from this contract to recipient, or simulate receiving by calling transferFrom where this contract is the spender
        // We need to ensure an allowed call that changes state is top-level. We'll call c.transfer(recipient, amount) and catch revert.
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances and rewards after
        uint256 balThisAfter = c.balanceOf(address(this));
        uint256 balRecAfter = c.balanceOf(recipient);
        uint256 balContractAfter = c.balanceOf(address(c));
        uint256 txRewardThisAfter = c.txReward(address(this));
        uint256 txRewardRecAfter = c.txReward(recipient);

        // General invariant rule to assert:
        // If the call reverted, then no state changed: balances and txRewards must be equal to before values.
        // If it did not revert, totalSupply must remain unchanged and the sum of observed balances for (this, recipient, contract) must equal their before-sum.
        // Additionally, when a non-revert transfer executed and amount >= minTxnAmount and contract had enough balance, exactly one of txReward for sender or recipient may increase (monotonic), and increases are non-negative.

        if (reverted) {
            assert(balThisAfter == balThisBefore && balRecAfter == balRecBefore && balContractAfter == balContractBefore && txRewardThisAfter == txRewardThisBefore && txRewardRecAfter == txRewardRecBefore && c.totalSupply() == beforeTotal);
        } else {
            // total supply preserved
            bool totalPreserved = (c.totalSupply() == beforeTotal);

            // sum preserved for the three observed accounts
            uint256 sumBefore = balThisBefore + balRecBefore + balContractBefore;
            uint256 sumAfter = balThisAfter + balRecAfter + balContractAfter;
            bool sumsEqual = (sumBefore == sumAfter);

            // txReward increases only for at most one of sender/recipient and never decreases
            bool txThisNotDecreased = txRewardThisAfter >= txRewardThisBefore;
            bool txRecNotDecreased = txRewardRecAfter >= txRewardRecBefore;

            // At most one increased (cannot assert which without knowing roles), so their decreases are impossible and both increases concurrently is allowed but guard asserts at-most-one increased
            bool atMostOneIncreased = !((txRewardThisAfter > txRewardThisBefore) && (txRewardRecAfter > txRewardRecBefore));

            assert(totalPreserved && sumsEqual && txThisNotDecreased && txRecNotDecreased && atMostOneIncreased);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing one state-changing call on c and ending with one assert
    // params:
    // recipient: target address to transfer to
    // amount: token amount tAmount to transfer
    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));

        // observe before-values
        uint256 totBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balRecBefore = c.balanceOf(recipient);
        uint256 balContractBefore = c.balanceOf(address(c));
        uint256 txRewardSenderBefore = c.txReward(address(this));
        uint256 txRewardRecBefore = c.txReward(recipient);

        bool reverted;
        // single top-level state-changing call, capture revert
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 totAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balRecAfter = c.balanceOf(recipient);
        uint256 balContractAfter = c.balanceOf(address(c));
        uint256 txRewardSenderAfter = c.txReward(address(this));
        uint256 txRewardRecAfter = c.txReward(recipient);

        // Single assert encoding the general rule for all inputs
        assert(
            // If reverted: nothing observable changed
            (reverted && totAfter == totBefore && balSenderAfter == balSenderBefore && balRecAfter == balRecBefore && balContractAfter == balContractBefore && txRewardSenderAfter == txRewardSenderBefore && txRewardRecAfter == txRewardRecBefore)
            ||
            // Else (succeeded): totalSupply preserved, sum of three balances preserved, and txRewards did not decrease
            (!reverted && totAfter == totBefore && (balSenderBefore + balRecBefore + balContractBefore) == (balSenderAfter + balRecAfter + balContractAfter) && txRewardSenderAfter >= txRewardSenderBefore && txRewardRecAfter >= txRewardRecBefore)
        );
    }

    receive() external payable {}
}

