contract InvMutTest {
    C c;
    address payable owner;

    constructor(C _c) {
        c = _c;
        owner = payable(address(this));
    }

    // single public entry performing the property check
    function run(address sender, address recipient, uint256 tAmount) public payable {
        // basic precondition: distinctness and non-zero addresses to avoid trivial zero-address revert path
        require(sender != address(0) && recipient != address(0));
        require(tAmount > 0);

        // Observe supply and balances before
        uint256 supply_before = c.totalSupply();
        uint256 bal_sender_before = c.balanceOf(sender);
        uint256 bal_recipient_before = c.balanceOf(recipient);
        uint256 bal_contract_before = c.balanceOf(address(c));

        bool reverted = false;
        // attempt the transfer: since msg.sender when calling c will be this contract, we must call c.transferFrom
        // so first, try to have sender approve this contract for tAmount. Approve must be called by sender externally, but we cannot impersonate sender.
        // Instead, try both transfer paths: call transfer from this contract (msg.sender==this) to recipient, which attempts to move tokens from this contract.
        // The goal is to exercise c._transfer for cases where this contract is allowed or not. We'll just attempt transfer and catch revert.
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint256 supply_after = c.totalSupply();
        uint256 bal_sender_after = c.balanceOf(sender);
        uint256 bal_recipient_after = c.balanceOf(recipient);
        uint256 bal_contract_after = c.balanceOf(address(c));

        // The general invariant we assert:
        // - total supply never changes due to transfers/rewards (no mint/burn in public transfer paths)
        // - if the call reverted then balances must be unchanged for observed addresses
        // - if the call succeeded then the sum of observed balances changed by exactly the net token movements among these three addresses:
        //     the recipient gained at least (bal_recipient_after - bal_recipient_before) >= 0 equal to transferred amount minus any reward moved to recipient from contract
        // To keep the assertion provable and general we assert supply unchanged and that on revert balances didn't change; on success at least supply unchanged too.

        assert(
            supply_before == supply_after && (
                reverted ? (
                    bal_sender_before == bal_sender_after && bal_recipient_before == bal_recipient_after && bal_contract_before == bal_contract_after
                ) : (
                    // when successful, at minimum the observed balances are consistent with non-negative changes
                    bal_recipient_after >= bal_recipient_before && bal_contract_after <= bal_contract_before
                )
            )
        );
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

