contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for the property-based test
    // parameters: sender and recipient are addresses to use as caller and recipient of transferFrom/transfer flows;
    // amount is the transfer amount; approveAmount is allowance we may set if using transferFrom path;
    // useTransferFrom flag selects whether to exercise transferFrom (true) or transfer (false).
    function run(address sender, address recipient, uint256 amount, uint256 approveAmount, bool useTransferFrom) public payable {
        require(sender != address(0) && recipient != address(0));

        // observe total supply before
        uint256 tBefore = c.totalSupply();

        // ensure InvMutTest (this contract) has some tokens to operate with: owner minted initial supply to deployer (c constructor),
        // but this test contract may not hold tokens. We will attempt to transfer by first getting tokens from the deployer (owner).
        // The contract c was deployed fresh with InvMutTest as msg.sender in the test harness; per harness rules, c was deployed
        // with constructor argument _c being the freshly deployed contract so owner is deployer. However we cannot rely on that,
        // instead we will attempt both flows but protect against reverts and record revert flag.

        // read balances and txReward before
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 txRewardSenderBefore = c.txReward(sender);
        uint256 txRewardRecipientBefore = c.txReward(recipient);

        bool reverted = false;

        // If using transferFrom, we need sender to approve this contract (InvMutTest) for approveAmount.
        // We cannot make sender externally call approve, so only attempt transferFrom when sender == address(this)
        // or when approveAmount==0 (which would likely revert). We still attempt call and catch revert.
        if (useTransferFrom) {
            // attempt to set allowance from sender to this contract only if sender is this contract (allowed by public API)
            if (sender == address(this)) {
                // approve spender msg.sender in c as this contract approving itself
                c.approve(address(this), approveAmount);
            }
            // try transferFrom(sender, recipient, amount) from this contract
            try c.transferFrom(sender, recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // attempt to call transfer as if msg.sender == sender; but in this test harness msg.sender is InvMutTest contract
            // so we can only succeed when sender == address(this). Otherwise call will either transfer from this contract's balance or revert.
            if (sender == address(this)) {
                try c.transfer(recipient, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // cannot impersonate other sender, so attempt transfer from this contract to recipient instead to exercise non-revert path
                try c.transfer(recipient, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        }

        // observe balances and txReward after
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 txRewardSenderAfter = c.txReward(sender);
        uint256 txRewardRecipientAfter = c.txReward(recipient);
        uint256 tAfter = c.totalSupply();

        // general rule:
        // - totalSupply must never change across a transfer attempt
        // - if the call did not revert, then the change in balances plus any rewarded tokens credited from contract cannot exceed the nominal tAmount movement
        //   specifically, recipient balance increase <= tAmount + possible reward credited to recipient, and sender decrease <= tAmount + possible reward credited to sender
        // - txReward for recipient/sender can only increase and at most by tAmount * rewardRate / percent
        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();

        // compute observed diffs safely
        bool totalSupplyInvariant = (tBefore == tAfter);

        bool senderBalanceNonIncrease;
        if (balSenderAfter <= balSenderBefore) {
            senderBalanceNonIncrease = true; // decreased or unchanged
        } else {
            senderBalanceNonIncrease = false;
        }

        bool recipientBalanceNonDecrease;
        if (balRecipientAfter >= balRecipientBefore) {
            recipientBalanceNonDecrease = true;
        } else {
            recipientBalanceNonDecrease = false;
        }

        uint256 maxPossibleReward = 0;
        // avoid overflow in multiplication: if amount * rewardRate would overflow, conservatively set maxPossibleReward to type max
        unchecked {
            maxPossibleReward = (amount * rewardRate) / percent;
        }

        bool txRewardRecipientValid = (txRewardRecipientAfter >= txRewardRecipientBefore) && (txRewardRecipientAfter - txRewardRecipientBefore <= maxPossibleReward);
        bool txRewardSenderValid = (txRewardSenderAfter >= txRewardSenderBefore) && (txRewardSenderAfter - txRewardSenderBefore <= maxPossibleReward);

        // If the operation reverted, we only require total supply invariant. If it didn't revert, require all invariants.
        assert(totalSupplyInvariant && (reverted || (senderBalanceNonIncrease && recipientBalanceNonDecrease && txRewardRecipientValid && txRewardSenderValid)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entrypoint for the property-based test
    // params: from and to are addresses to treat as sender and recipient; amount is transfer amount; useTransferFrom selects transferFrom vs transfer
    function run(address from, address to, uint256 amount, bool useTransferFrom, uint256 approveAmount) public payable {
        require(from != address(0) && to != address(0));

        // Observe global and per-account state before
        uint256 totalBefore = c.totalSupply();
        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);
        uint256 balContractBefore = c.balanceOf(address(c));
        uint256 txRewardFromBefore = c.txReward(from);
        uint256 txRewardToBefore = c.txReward(to);

        bool reverted;

        if (useTransferFrom) {
            // If from == this contract, we can approve; otherwise approve will be a no-op for that owner and likely irrelevant.
            if (from == address(this)) {
                c.approve(address(this), approveAmount);
            }
            // attempt transferFrom as a top-level statement and catch revert
            try c.transferFrom(from, to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // attempt transfer as this contract's caller. If caller isn't the 'from' parameter, it's still a valid call and we exercise public behavior.
            try c.transfer(to, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Observe after state
        uint256 totalAfter = c.totalSupply();
        uint256 balFromAfter = c.balanceOf(from);
        uint256 balToAfter = c.balanceOf(to);
        uint256 balContractAfter = c.balanceOf(address(c));
        uint256 txRewardFromAfter = c.txReward(from);
        uint256 txRewardToAfter = c.txReward(to);

        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();

        // Compute observed deltas safely (use >= comparisons to avoid underflow in assert)
        bool totalInvariant = (totalBefore == totalAfter);

        // The observable token mass across (from + to + contract) should not increase when a transfer succeeds
        // i.e., (from + to + contract)_after <= (from + to + contract)_before + possible rewards granted (but rewards are taken from contract balance, so mass should remain equal)
        // Simpler safe invariant: when call succeeds, the sum of balances of from+to+contract remains equal to before.
        uint256 sumBefore = balFromBefore + balToBefore + balContractBefore;
        uint256 sumAfter = balFromAfter + balToAfter + balContractAfter;

        // txReward values are monotonic non-decreasing and any increase for an account is at most amount * rewardRate / percent when call succeeds
        bool txFromNonDecr = (txRewardFromAfter >= txRewardFromBefore);
        bool txToNonDecr = (txRewardToAfter >= txRewardToBefore);

        // compute max possible reward (conservative using multiplication in unchecked to avoid revert inside test)
        uint256 maxReward;
        unchecked {
            maxReward = (amount * rewardRate) / percent;
        }

        bool txFromBounded = (txRewardFromAfter - txRewardFromBefore) <= maxReward;
        bool txToBounded = (txRewardToAfter - txRewardToBefore) <= maxReward;

        // If the call reverted we only require total supply unchanged. If it didn't revert then require total supply unchanged and sum invariant and txReward monotonic & bounded.
        assert(totalInvariant && (reverted || (sumAfter == sumBefore && txFromNonDecr && txToNonDeCrOrBounded(txFromBounded, txFromNonDeCr(txFromNonDeCr_placeholder())) && txToNonDeCrAndBounded(txToNonDeCr_placeholder(), txToBounded))));
    }

    // The following tiny helper shims are never called; they exist only to allow expressing the complex assert in one expression
    // but must be present as external functions are not allowed. Implement trivial view helpers used in the assert expression.
    function txFromNonDeCr(bool v) internal pure returns (bool) { return v; }
    function txFromNonDeCr_placeholder() internal pure returns (bool) { return true; }
    function txToNonDeCr_placeholder() internal pure returns (bool) { return true; }
    function txToNonDeCrAndBounded(bool a, bool b) internal pure returns (bool) { return a && b; }
    function txToNonDeCr(bool v) internal pure returns (bool) { return v; }

    receive() external payable {}
}

