    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0), "nonzero addrs");
        require(sender != recipient, "distinct");
        // Precondition: amount > 0 to be meaningful
        require(amount > 0, "positive amount");

        // We will act as msg.sender being this contract; the c was deployed fresh with owner set to deployer
        // We must ensure sender has enough balance to transfer amount. We cannot manipulate private state directly,
        // but we can use c.transfer to move tokens to sender if caller (this contract) has tokens. Initially c minted to deployer,
        // which is NOT this contract. So to make test feasible, we try to use approve/transferFrom path: we ask sender to have approved this contract.
        // However we cannot cause arbitrary external accounts to call approve in this single-transaction test.
        // Therefore we instead use c.transfer to move tokens from this contract (msg.sender here) to sender if this contract has balance.
        // To ensure the test can be reached by the checker, we avoid assuming balances; instead we check the call behaviour and express property conditionally
        // after observing whether the transfer/transferFrom reverted.

        // Observe initial balances and allowance
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 allowanceBefore = c.allowance(sender, address(this));

        // Try to perform transferFrom(sender -> recipient) as this contract.
        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(sender, address(this));

        // General rule: if transferFrom did NOT revert then balances must reflect the transfer amount and allowance decreased by amount (unless allowance was max uint)
        // We cannot underflow in assert; express as equalities using checked additions.
        // allowance behavior: contract uses _approve subtraction with SafeMath, so it will revert if allowance < amount. Thus non-revert implies allowanceBefore >= amount and allowanceAfter == allowanceBefore - amount.
        // Balances: non-revert implies sender balance decreased by amount and recipient increased by amount.

        assert(
            reverted
            || (
                balSenderAfter + amount == balSenderBefore
                && balRecipientBefore + amount == balRecipientAfter
                && allowanceBefore >= amount
                && allowanceAfter + amount == allowanceBefore
            )
        );
    }

    receive() external payable {}
}

