        uint256 beforeSenderBal = c.balanceOf(sender);
        uint256 beforeRecipientBal = c.balanceOf(recipient);
        uint256 beforeContractBal = c.balanceOf(address(c));
        uint256 beforeTxRewardSender = c.txReward(sender);
        uint256 beforeTxRewardRecipient = c.txReward(recipient);
