        uint256 afterSenderBal = c.balanceOf(sender);
        uint256 afterRecipientBal = c.balanceOf(recipient);
        uint256 afterContractBal = c.balanceOf(address(c));
        uint256 afterTxRewardSender = c.txReward(sender);
        uint256 afterTxRewardRecipient = c.txReward(recipient);

        // General rule asserted:
        // If transferFrom did NOT revert, then sender balance decreased by exactly amount and recipient increased by exactly amount.
        // Additionally, if amount >= minTxn AND contract had >= rewardAmount before the call, then exactly one of txReward for sender or recipient increased by rewardAmount
        // depending on who is the allowed role beneficiary. Because allowedRoles is private we cannot know which side is allowed; however behavior in contract
        // either awards txReward to recipient (buy path) or sender (sell path). We assert that at most one of their txReward deltas equals rewardAmount and the other is unchanged.

