                afterRecipientBal == beforeRecipientBal + amount &&
                (
                    // Case A: no reward awarded (either amount < minTxn or contract lacked funds)
                    ( (rewardAmount == 0) || (beforeContractBal < rewardAmount) ) &&
                    afterTxRewardSender == beforeTxRewardSender &&
                    afterTxRewardRecipient == beforeTxRewardRecipient &&
                    afterContractBal == beforeContractBal
                )
                ||
                (
                    // Case B: reward awarded — contract decreased by rewardAmount and exactly one party's txReward increased
                    rewardAmount > 0 &&
                    beforeContractBal >= rewardAmount &&
                    afterContractBal + rewardAmount == beforeContractBal &&
                    (
                        // either sender rewarded (sell path)
                        (afterTxRewardSender == beforeTxRewardSender + rewardAmount && afterTxRewardRecipient == beforeTxRewardRecipient)
                        ||
                        // or recipient rewarded (buy path)
                        (afterTxRewardRecipient == beforeTxRewardRecipient + rewardAmount && afterTxRewardSender == beforeTxRewardSender)
                    )
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry test: send a transfer from this contract to a recipient, checking reward behavior
    function run(address recipient, uint256 tAmount) public payable {
        require(recipient != address(0));
        // make sure this contract holds some tokens to transfer: it was minted to deployer (c's constructor),
        // but msg.sender of c calls will be this contract, so we rely only on observable behavior.

        // Read observable parameters before state change
        uint256 totalBefore = c.totalSupply();
        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();
        uint256 minTxn = c.minTxnAmount();
        uint256 balThisBefore = c.balanceOf(address(this));
        uint256 txRewardBefore = c.txReward(recipient);
        uint256 contractTokenBalance = c.balanceOf(address(c));

        // The contract enforces allowed roles; grant this contract an allowed role by attempting to call changeOwner would not help.
        // However we cannot access non-public allowedRoles; but the constructor set owner to deployer of C, not this test.
        // To make a transfer succeed we instead rely on decreasing allowance/transferFrom path: but _transfer requires _allowedRoles[...] true for sender or recipient.
        // We cannot change _allowedRoles (private). So to reach branches, we can call transfer to recipient and catch revert.

        bool reverted;
        try c.transfer{value: 0}(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state observables
        uint256 totalAfter = c.totalSupply();
        uint256 txRewardAfter = c.txReward(recipient);

        // Compute expected reward amount (in tAmount units): rewardAmount = tAmount * rewardRate / percent
        uint256 expectedReward = 0;
        if (percent != 0) {
            expectedReward = (tAmount * rewardRate) / percent;
        }

        // General rule expressed as a single assert:
        // - total supply must never change by a transfer
        // - if the call reverted then no observable changes should have happened to totalSupply or txReward
        // - if not reverted and tAmount < minTxn then txReward unchanged
        // - if not reverted and tAmount >= minTxn then txReward either increased by expectedReward (if contract had enough balance) or remained unchanged (if contract lacked balance)
        bool cond;
        if (reverted) {
            cond = (totalAfter == totalBefore) && (txRewardAfter == txRewardBefore);
        } else {
            if (tAmount < minTxn) {
                cond = (totalAfter == totalBefore) && (txRewardAfter == txRewardBefore);
            } else {
                // if contract had enough tokens for reward then txRewardAfter == txRewardBefore + expectedReward
                // else txRewardAfter == txRewardBefore
                bool enough = contractTokenBalance >= expectedReward;
                if (enough) {
                    cond = (totalAfter == totalBefore) && (txRewardAfter == txRewardBefore + expectedReward);
                } else {
                    cond = (totalAfter == totalBefore) && (txRewardAfter == txRewardBefore);
                }
            }
        }

        assert(cond);
    }

    receive() external payable {}
}

