contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entrypoint taking parameters to exercise transfer behavior
    function run(address sender, address recipient, uint256 amount) public payable {
        // preconditions: ensure sender and recipient are not contract zero (we will test zero-address revert behavior below)
        // We also avoid calling with address(c) or address(this) as special cases — but those are allowed.
        require(sender != address(0) || recipient != address(0), "at least one zero to test revert");

        // Observe total supply before
        uint256 totalBefore = c.totalSupply();

        // Observe balances before (use try/catch to capture reverts when calling transferFrom if needed)
        // We'll attempt to simulate a transfer by calling c.transferFrom(sender, recipient, amount) as msg.sender is this contract.
        // But transferFrom requires allowance; instead we will call c.transfer(recipient, amount) as msg.sender==sender is not possible.
        // To exercise both branches, we will call transferFrom and catch revert; the assertion will relate reversion to invalid inputs.

        bool reverted = false;
        // Attempt transferFrom: this will only succeed if this contract has allowance from sender; if not it should revert with allowance error
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempt, observe balances
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 totalAfter = c.totalSupply();

        // General rule: total supply unchanged; and if the call did not revert then
        // the sum of observed balances changes by at most amount (i.e., recipient increased by amount and sender decreased by amount)
        // If either address is zero or amount == 0 the call must revert.
        // We express this as: totalBefore == totalAfter AND
        // ( ( (sender==address(0) || recipient==address(0) || amount==0) ==> reverted ) AND ( !reverted ==> (balRecipientAfter >= balSenderAfter ? balRecipientAfter - balSenderAfter == (c.balanceOf(recipient) - c.balanceOf(sender)) : true) ) )
        // Simplify to check: total unchanged, and if not reverted then balance difference between recipient and sender increased by at most amount and the exact transferred amount <= amount.

        // Compute observable sum change: note reading balances twice is allowed; use the ones read above.
        // But we must form a single assert using these values and params.

        // Formulate: totalBefore == totalAfter AND (
        //   (sender==address(0) || recipient==address(0) || amount==0) ? reverted : !reverted && (
        //        // when not reverted, recipient's balance increased by at most amount and sender decreased by at most amount
        //        (balRecipientAfter >= c.balanceOf(recipient) - 0) && // tautology to use variables
        //        true
        //   )
        // )

        // For clarity and to be a meaningful invariant we assert:
        // 1) total supply unchanged
        // 2) if sender or recipient is zero or amount==0 then call reverted
        // 3) if call did not revert then (balRecipientAfter - c.balanceOf(recipient) == 0) is trivially true, so instead assert that the net change in (sender+recipient) equals 0 or +/- amount: before sum minus after sum is either amount (sender paid) or -amount (recipient paid) or 0.

        // To compute before sum we need balances before; fetch them now (we only fetched after). Re-fetch balances before by calling balanceOf again is fine because we didn't store earlier — adjust: fetch before now impossible. To respect single assert, we will re-call balanceOf to get before values by using amount argument: but must ensure all reads are allowed. We'll instead require that total unchanged AND
        // if sender==address(0) || recipient==address(0) || amount==0 then reverted, else not necessarily reverted (could revert for lack of allowance). To make a provable rule, assert that zero-address or zero-amount inputs always cause revert.

        assert(totalBefore == totalAfter && ((sender == address(0) || recipient == address(0) || amount == 0) ? reverted : true));
    }

    // receive fallback to accept ETH if needed
    receive() external payable {}
}

