    // Single entry exercising transferFrom and checking supply, recipient balance, and allowance delta
    function run(address sender, address recipient, uint256 amount) public payable {
        // bound amount to totalSupply to avoid impossible large transfers
        require(amount <= c.totalSupply());

        // read before values
        uint256 totalBefore = c.totalSupply();
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 allowanceBefore = c.allowance(sender, address(this));

        // perform the transferFrom and capture whether it reverted
        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint256 totalAfter = c.totalSupply();
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(sender, address(this));

        // General rule:
        // - totalSupply is always preserved (revert leaves state unchanged, success should not change supply)
        // - if call succeeded then recipient balance increased by exactly amount AND allowance decreased by exactly amount
        // - if call reverted then balances and allowance remain unchanged
        assert(
            // total supply unchanged in all cases
            totalAfter == totalBefore
            && (
                reverted
                ? (
                    // on revert nothing should have changed
                    balRecipientAfter == balRecipientBefore && allowanceAfter == allowanceBefore
                  )
                : (
                    // on success recipient gained exactly amount and allowance decreased exactly by amount
                    balRecipientAfter == balRecipientBefore + amount && allowanceBefore >= amount && allowanceAfter + amount == allowanceBefore
                  )
            )
        );
    }

